// =========================================================================
// WF-1: RECONCILED ADDITIVE DYNAMIC PRICING ENGINE
// =========================================================================

const item = $input.item.json;
const fields = item.fields || {};

// 1. Core Property Base Rates & Limits
const basePrice = Number(fields["Base Nightly Price"]) || 100000;
const minPrice = Number(fields["Min Price"]) || 70000;
const maxPrice = Number(fields["Max Price"]) || 150000;

// 2. Extract Linked Competitor Market Rates (Table 4)
const competitorRates = fields["Competitor Observed Rates"] || []; 
let deltaCompetitor = 0.00;

if (competitorRates.length > 0) {
  const compAvg = competitorRates.reduce((sum, rate) => sum + Number(rate), 0) / competitorRates.length;
  if (compAvg > basePrice) {
    deltaCompetitor = 0.10; // +10% boost if competitor avg higher than base
  }
}

// 3. Extract Local Event Impact Signals (Table 5)
const eventImpactLevel = (fields["Highest Active Event Impact"] || "NONE").toUpperCase();
let mEvent = 0.00;

if (eventImpactLevel === "HIGH") {
  mEvent = 0.25;
} else if (eventImpactLevel === "MEDIUM") {
  mEvent = 0.10;
}

// 4. Weekend Multiplier Check (Fri/Sat)
const today = new Date();
const dayOfWeek = today.getDay(); // 0 = Sun, 5 = Fri, 6 = Sat
const isWeekend = (dayOfWeek === 5 || dayOfWeek === 6);
const mWeekend = isWeekend ? 0.15 : 0.00;

// 5. Reconciled Additive Factor Calculation
// Recommended Price = Base Price * (1 + Δ Competitor + M Event + M Weekend)
const rawMultiplier = 1 + deltaCompetitor + mEvent + mWeekend;
const calculatedPrice = Math.round(basePrice * rawMultiplier);

// 6. Enforce Safety Floor & Ceiling Boundaries
const finalRecommendedPrice = Math.min(Math.max(calculatedPrice, minPrice), maxPrice);

// 7. Structure Output Object
return {
  json: {
    property_record_id: item.id,
    property_id: fields["Property ID"] || "PROP-001",
    base_price: basePrice,
    min_price: minPrice,
    max_price: maxPrice,
    calculated_price: calculatedPrice,
    final_recommended_price: finalRecommendedPrice,
    is_weekend: isWeekend ? "YES" : "NO",
    event_impact: eventImpactLevel,
    delta_competitor: deltaCompetitor,
    evaluated_at: new Date().toISOString()
  }
};
